import{_ as e,o as s,c as t,a0 as n}from"./chunks/framework.jwovEGr5.js";const u=JSON.parse('{"title":"Day 16: /proc/stat과 CPU Usage","description":"","frontmatter":{},"headers":[],"relativePath":"outta-space/project/Day-16-proc-stat과-CPU-Usage.md","filePath":"outta-space/project/Day-16-proc-stat과-CPU-Usage.md"}'),l={name:"outta-space/project/Day-16-proc-stat과-CPU-Usage.md"};function o(c,a,i,p,d,r){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="day-16-proc-stat과-cpu-usage" tabindex="-1">Day 16: /proc/stat과 CPU Usage <a class="header-anchor" href="#day-16-proc-stat과-cpu-usage" aria-label="Permalink to &quot;Day 16: /proc/stat과 CPU Usage&quot;">​</a></h1><p>Linux의 <code>/proc/stat</code>에서 전체 CPU 누적 시간을 두 번 읽고, 두 snapshot의 차이로 CPU usage를 계산하는 collector를 구현했다.</p><h2 id="proc-stat의-cpu-시간" tabindex="-1">/proc/stat의 CPU 시간 <a class="header-anchor" href="#proc-stat의-cpu-시간" aria-label="Permalink to &quot;/proc/stat의 CPU 시간&quot;">​</a></h2><p>첫 번째 <code>cpu</code> 행은 모든 CPU core를 합산한 누적 시간이다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cpu user nice system idle iowait irq softirq steal guest guest_nice</span></span></code></pre></div><p>각 숫자는 순간 사용률이 아니라 시스템 부팅 이후 해당 상태에서 소비한 누적 CPU 시간이다. <code>guest</code>와 <code>guest_nice</code>는 이미 <code>user</code>와 <code>nice</code>에 포함되므로 total에 다시 더하지 않았다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>idle_all = idle + iowait</span></span>
<span class="line"><span></span></span>
<span class="line"><span>non_idle =</span></span>
<span class="line"><span>    user + nice + system</span></span>
<span class="line"><span>    + irq + softirq + steal</span></span>
<span class="line"><span></span></span>
<span class="line"><span>total = idle_all + non_idle</span></span></code></pre></div><h2 id="첫-행-읽기와-파싱" tabindex="-1">첫 행 읽기와 파싱 <a class="header-anchor" href="#첫-행-읽기와-파싱" aria-label="Permalink to &quot;첫 행 읽기와 파싱&quot;">​</a></h2><p><code>fopen()</code>으로 <code>/proc/stat</code>을 열고 <code>fgets()</code>로 첫 행을 문자열 buffer에 읽었다. <code>sscanf()</code>로 label과 8개의 누적값을 구조체에 저장했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>%3s  → 최대 3글자의 label</span></span>
<span class="line"><span>%llu → unsigned long long 값</span></span></code></pre></div><p>Label 한 개와 숫자 8개를 읽으므로 <code>sscanf()</code> 반환값이 정확히 9인지 검사하고, <code>strcmp()</code>로 label이 <code>cpu</code>인지 확인했다.</p><p>누적값에는 <code>unsigned long long</code>을 사용했다. <code>sscanf()</code>에는 숫자를 저장할 구조체 멤버의 주소를 전달했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>label          → char 배열 자체를 전달</span></span>
<span class="line"><span>&amp;times-&gt;user   → 숫자를 저장할 멤버의 주소</span></span></code></pre></div><h2 id="snapshot과-cpu-usage" tabindex="-1">Snapshot과 CPU usage <a class="header-anchor" href="#snapshot과-cpu-usage" aria-label="Permalink to &quot;Snapshot과 CPU usage&quot;">​</a></h2><p>한 번 읽은 누적값만으로는 현재 사용률을 알 수 없다. 두 snapshot 사이에 3초 간격을 두고 차이를 계산했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>before snapshot</span></span>
<span class="line"><span>→ sleep(3)</span></span>
<span class="line"><span>→ after snapshot</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>delta_total = after_total - before_total</span></span>
<span class="line"><span>delta_idle  = after_idle - before_idle</span></span>
<span class="line"><span></span></span>
<span class="line"><span>usage =</span></span>
<span class="line"><span>    (delta_total - delta_idle)</span></span>
<span class="line"><span>    / delta_total</span></span>
<span class="line"><span>    × 100</span></span></code></pre></div><p>정수 나눗셈으로 소수점이 사라지지 않도록 <code>double</code>로 변환했다. 실제 실행에서는 다음과 같은 결과를 확인했다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CPU usage: 0.54%</span></span></code></pre></div><p>환경의 실행 부하에 따라 결과는 매번 달라진다.</p><h2 id="방어-검사" tabindex="-1">방어 검사 <a class="header-anchor" href="#방어-검사" aria-label="Permalink to &quot;방어 검사&quot;">​</a></h2><p>다음 경우를 오류로 처리했다.</p><ul><li><code>/proc/stat</code> open 또는 read 실패</li><li>예상하지 못한 EOF</li><li><code>sscanf()</code>가 9개 필드를 모두 변환하지 못함</li><li>첫 label이 <code>cpu</code>가 아님</li><li><code>fclose()</code> 실패</li><li>누적 counter가 이전 snapshot보다 작아짐</li><li><code>delta_total == 0</code></li><li><code>delta_idle &gt; delta_total</code></li></ul><p><code>read_cpu_times()</code>는 기본 status를 실패로 두고, 파싱에 성공한 경우에만 0으로 바꿨다. <code>fopen()</code> 이후의 모든 경로는 공통 <code>cleanup</code> label에서 <code>fclose()</code>를 시도한다.</p><h2 id="strace-관찰" tabindex="-1">strace 관찰 <a class="header-anchor" href="#strace-관찰" aria-label="Permalink to &quot;strace 관찰&quot;">​</a></h2><p>다음 system call을 중심으로 실행 흐름을 확인했다.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">strace</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -yy</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> trace=openat,read,close,clock_nanosleep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  ./proc/cpu-usage</span></span></code></pre></div><p>관찰한 lifecycle은 다음과 같다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openat(&quot;/proc/stat&quot;)</span></span>
<span class="line"><span>→ read()</span></span>
<span class="line"><span>→ close()</span></span>
<span class="line"><span>→ clock_nanosleep()</span></span>
<span class="line"><span>→ openat(&quot;/proc/stat&quot;)</span></span>
<span class="line"><span>→ read()</span></span>
<span class="line"><span>→ close()</span></span>
<span class="line"><span>→ CPU usage 출력</span></span></code></pre></div><p>Source에서는 <code>sleep(3)</code>을 사용했지만 libc를 거친 실제 system call은 <code>clock_nanosleep()</code>으로 관찰될 수 있다. Program 시작 시 보이는 <code>/etc/ld.so.cache</code>와 <code>libc.so.6</code> 접근은 dynamic linker가 공유 라이브러리를 읽는 과정이다.</p><h2 id="linux-system-software-직무와의-연결" tabindex="-1">Linux System Software 직무와의 연결 <a class="header-anchor" href="#linux-system-software-직무와의-연결" aria-label="Permalink to &quot;Linux System Software 직무와의 연결&quot;">​</a></h2><p><code>sysmon-agent</code>의 CPU collector는 같은 원리로 <code>/proc/stat</code>을 주기적으로 읽는다. Metric은 단일 누적값이 아니라 이전 snapshot과 현재 snapshot의 차이를 이용해 계산해야 하며, collector는 이전 상태를 다음 주기까지 유지해야 한다.</p><h2 id="learned" tabindex="-1">Learned <a class="header-anchor" href="#learned" aria-label="Permalink to &quot;Learned&quot;">​</a></h2><ul><li><code>/proc/stat</code>의 CPU 값은 부팅 후 누적 시간이다.</li><li>CPU usage를 구하려면 시간 간격을 둔 두 snapshot이 필요하다.</li><li><code>guest</code>와 <code>guest_nice</code>를 다시 더하면 CPU 시간을 중복 계산한다.</li><li><code>sscanf()</code> 반환값으로 실제 변환된 필드 수를 검사해야 한다.</li><li><code>/proc</code> 파일도 open, read, close의 resource lifecycle을 가진다.</li><li>누적 counter의 역행과 0인 delta를 검사해야 안전하게 계산할 수 있다.</li></ul><h2 id="apis" tabindex="-1">APIs <a class="header-anchor" href="#apis" aria-label="Permalink to &quot;APIs&quot;">​</a></h2><ul><li><code>fopen()</code></li><li><code>fgets()</code></li><li><code>sscanf()</code></li><li><code>strcmp()</code></li><li><code>ferror()</code></li><li><code>fclose()</code></li><li><code>sleep()</code></li></ul><h2 id="commands" tabindex="-1">Commands <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;Commands&quot;">​</a></h2><ul><li><code>head -n 1 /proc/stat</code></li><li><code>watch -n 1 &#39;head -n 1 /proc/stat&#39;</code></li><li><code>strace -yy -e trace=openat,read,close,clock_nanosleep</code></li></ul><h2 id="mistakes" tabindex="-1">Mistakes <a class="header-anchor" href="#mistakes" aria-label="Permalink to &quot;Mistakes&quot;">​</a></h2><ul><li><code>fgets()</code>로 읽은 변수는 <code>buffer</code>인데 처음 <code>sscanf()</code>에 존재하지 않는 <code>line</code>을 전달했다.</li><li>성공 경로에서 <code>read_cpu_times()</code>의 반환값을 처음에는 작성하지 않았다.</li><li>오류 경로마다 <code>fclose()</code>와 <code>return</code>이 반복되어 공통 cleanup 구조로 정리했다.</li></ul><h2 id="todo" tabindex="-1">TODO <a class="header-anchor" href="#todo" aria-label="Permalink to &quot;TODO&quot;">​</a></h2><ul><li>측정 간격을 상수 또는 인자로 분리</li><li>CPU 계산 로직을 별도 함수로 분리</li><li>여러 core의 <code>cpu0</code>, <code>cpu1</code> 행별 usage 계산은 필요할 때 확장</li></ul><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><code>/proc/meminfo</code>를 읽고 memory usage를 계산한다.</li></ul>`,44)])])}const g=e(l,[["render",o]]);export{u as __pageData,g as default};
